# Check if there's a flag in the ciphertext - try to decrypt ECB
# The vault cipher_hex: "779ad6c2a703cb25752de716065f2cbd7670940f40ce5155722c02ba778cd48005eff3b2eb4c"
# That's 44 hex chars = 22 bytes for vault, and the "item=vault" input is very short
# This suggests the encryption isn't directly the item name

# Let me compare blocks between different items for ECB patterns
python3 << 'EOF'
import binascii

items = {
    "1": "65b9e3e4b0118a783b2bb850024d7bb36669a407028a0442623a00f021f7c28252a4f8f6af119971216ea440000472b26767",
    "2": "75bff0eca850943d2e26b74b090871af342896554d880b45277a14b87cc8c2d502f3b7eaba11957c3f25b3510e037afc763c915147894b",
    "3": "7cb9f9f1b45d813d2e26a357094d6fbd602cd545569c07582e774ebb779a839711e4b9b4f9119e722122b9520e037afc662c81534c890c5e2c3e57bf7eca838a56b8b9",
    "4": "67bff2f2b943d84c0c6ea5500a007cae6d698753449817542c7d51ad33c8879558b3e0e0ae6e8a783d21a451380479fc2d79c60713dd035e303e44ac7acc8b8f54b1f2e1fc509b7e283da50515086bb5713ed5504d91095e353341ae3d",
    "vault": "779ad6c2a703cb25752de716065f2cbd7670940f40ce5155722c02ba778cd48005eff3b2eb4c",
    "90311": "63b3e4f1ae589b69282af657021b74b9632c87164698065831775bb033ca83805ab3e3abfc659d703d21a44415143dae713f9c535598171136715fbb7d80c2bc6e90dbc49b6ec94212",
}

# Check if block 2 of item 4 matches block 2 of item 90311
# (both relate to report 90311 which has a flag)
data4 = binascii.unhexlify(items["4"])
data90311 = binascii.unhexlify(items["90311"])

print(f"Item 4 blocks: {len(data4)//16}")
print(f"Item 90311 blocks: {len(data90311)//16}")

# Check if item 4 block 2 matches item 90311 block 1
for i in range(0, min(len(data4), 48), 16):
    block4 = data4[i:i+16]
    for j in range(0, len(data90311), 16):
        block90311 = data90311[j:j+16]
        if block4 == block90311:
            print(f"MATCH: item4 block {i//16} == item90311 block {j//16}")

# Check all pairwise block comparisons
all_data = {}
for k, v in items.items():
    all_data[k] = binascii.unhexlify(v)

for k1, d1 in all_data.items():
    for k2, d2 in all_data.items():
        if k1 >= k2:
            continue
        for i in range(0, len(d1), 16):
            b1 = d1[i:i+16]
            for j in range(0, len(d2), 16):
                b2 = d2[j:j+16]
                if b1 == b2 and len(b1) == 16:
                    print(f"MATCH: {k1} block {i//16} == {k2} block {j//16}")

EOF

